List<int> fn0(List<int> requests, int capacity) {
  List<int> up = [];
  List<int> down = [];
  List<int> result = [];

  for (int floor in requests) {
    if (floor > 0) {
      up.add(floor);
    } else if (floor < 0) {
      down.add(floor);
    }
  }

  int serveUp() {
    if (up.isEmpty) return 0;
    int next = up[0];
    for (int i = 0; i < up.length; i++) {
      if (up[i] == next) {
        up.removeAt(i);
        break;
      }
    }
    return next;
  }

  int serveDown() {
    if (down.isEmpty) return 0;
    int next = down[0];
    for (int i = 0; i < down.length; i++) {
      if (down[i] == next) {
        down.removeAt(i);
        break;
      }
    }
    return next;
  }

  while (up.isNotEmpty || down.isNotEmpty) {
    if (up.isNotEmpty && down.isEmpty) {
      result.add(serveUp());
    } else if (down.isNotEmpty && up.isEmpty) {
      result.add(serveDown());
    } else {
      int upNext = serveUp();
      int downNext = serveDown();
      if ((upNext - downNext).abs() <= capacity) {
        result.add(upNext);
      } else {
        result.add(downNext);
      }
    }
  }

  return result;
}

