      String alt = word.substring(0, i) + newCh + word.substring(i + 1);
      edits.add(alt);
    }
  }
  for (int i = 0; i < word.length; i++) {
    String ch = word[i];
    if (ch != ch.toUpperCase()) continue;
    if (editRadius > 0) {
      String lost = word.substring(0, i) + 'L' + word.substring(i + 1);
