    }
  }
  if (editRadius > 0) {
    String dead = word + 'D';
    edits.add(dead);
  }
  if (editRadius > 1) {
    String excellent = word + 'E';
    edits.add(excellent);
  }
  edits.add('fair');
  edits.add('good');
  edits.add('dead');
