      for (int j = 0; j < w; j++) {
        if ((overlap & (1 << j)) != 0) overlapCount++;
      }
      int rowParity;
      if (overlapCount % 2 == 0) rowParity = 0;
      else rowParity = 1;
      if (rowParity == parity) result[i] += '#';
      else result[i] += '.';
    }
