int fn0(List<String> symbols, int targetNetCharge) {
  List<int> dp = List.filled(targetNetCharge + 1, 1000000);
  dp[0] = 0;
  for (String symbol in symbols) {
    int charCode = symbol.codeUnitAt(0);
    int netCharge = (charCode - 64).abs();
