    for (int j = absCharge; j <= targetNetCharge; j++) {
      if (dp[j - absCharge] != 1000000) {
        int nextCount = dp[j - absCharge] + 1;
        if (nextCount < dp[j]) {
          dp[j] = nextCount;
        }
      }
    }
  }
  return dp[targetNetCharge] == 1000000 ? -1 : dp[targetNetCharge];
}

