List<int> fn0(String dna, List<int> cycleStarts, int cycleLen) {
  Map<String, int> counts = {};
  for (int i = 0; i < dna.length; i++) {
    counts[dna[i]] = (counts[dna[i]] ?? 0) + 1;
  }

  int total = dna.length;
  List<int> missing = [];
  for (int c = 48; c <= 57; c++) {
    String ch = String.fromCharCode(c);
    if (counts[ch] != null) {
      int missingCount = total - counts[ch]!;
      if (missingCount > 0) {
        missing.add(missingCount);
      }
    }
  }

  if (missing.isEmpty) {
    return [0, 0];
  }

  List<int> prefix = [];
  int sum = 0;
  for (int m in missing) {
    sum += m;
    prefix.add(sum);
  }

  int n = missing.length;
  List<int> dp = List.filled(n + 1, 1000000);
  dp[0] = 0;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      int windowSum = prefix[i] - prefix[j];
      int windowCount = i - j;
      int remainder = windowSum % windowCount;
      int gcdVal = windowCount;
      while (remainder != 0) {
        int t = remainder;
        remainder = gcdVal % remainder;
        gcdVal = t;
      }
      int lcmVal = windowCount ~/ gcdVal;
      int periodStart = (cycleStarts[0] + windowCount - 1) % cycleLen;
      for (int k = 0; k < cycleLen; k++) {
        if ((periodStart + k) % lcmVal == 0) {
          int cost = (dp[j] + windowCount + k) % 1000000;
          if (cost < dp[i]) {
            dp[i] = cost;
          }
        }
      }
    }
  }

  return [dp[n], n];
}

