bool _nextCombination(List<int> indices, int k, int n) {
  for (int i = k - 1; i >= 0; i--) {
    if (indices[i] < i + n - k) {
      indices[i]++;
      for (int j = i + 1; j < k; j++) {
        indices[j] = indices[j - 1] + 1;
      }
      return true;
    }
  }
  return false;
}

