    return;
  }

  int total = 1;
  for (int i = 1; i <= k; i++) {
    total *= i;
  }
  for (int i = k + 1; i <= n; i++) {
    total *= i;
  }
  if (k != 0) {
    int denom = 1;
    for (int i = 1; i <= k; i++) {
      denom *= i;
    }
