Map<String, int> fn0(List<int> durations, int targetDuration, int maxPairs) {
  if (targetDuration <= 0 || maxPairs <= 0 || durations.isEmpty) {
    return {"pairCount": 0, "mashupDuration": 0};
  }

  Set<int> uniqueDurations = {};
  for (int d in durations) {
    if (d > 0) {
      uniqueDurations.add(d);
    }
  }
  List<int> sortedDurations = uniqueDurations.toList()
    ..sort((a, b) => a.compareTo(b));

  Map<int, int> freq = {};
  for (int d in durations) {
    if (d > 0) {
      freq[d] = (freq[d] ?? 0) + 1;
    }
  }

  int pairCount = 0;
  int mashupDuration = 0;

  for (int i = 0; i < sortedDurations.length; i++) {
    int first = sortedDurations[i];
    if (first > targetDuration || freq[first] == 0) {
      continue;
    }

    for (int j = i; j < sortedDurations.length; j++) {
      int second = sortedDurations[j];
      if (second > targetDuration - first || freq[second] == 0) {
        continue;
      }

      if (first == second) {
        if (freq[first]! >= 2) {
          int pairs = (freq[first]! ~/ 2).min(maxPairs - pairCount);
          pairCount += pairs;
          mashupDuration += pairs * first;
        }
      } else {
        if (freq[first]! >= 1 && freq[second]! >= 1) {
          int pairs = 1.min(maxPairs - pairCount);
          pairCount += pairs;
          mashupDuration += first + second;
        }
      }

      if (pairCount >= maxPairs) {
        break;
      }
    }

    if (pairCount >= maxPairs) {
      break;
    }
  }

  return {"pairCount": pairCount, "mashupDuration": mashupDuration};
}

