class Quaternion {
  final double r, i, j, k;

  factory Quaternion(double r, double i, double j, double k) {
    return _normalize(Quaternion._(r, i, j, k));
  }

  Quaternion._(this.r, this.i, this.j, this.k);

  Quaternion operator +(Quaternion other) {
    return Quaternion._(r + other.r, i + other.i, j + other.j, k + other.k);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion._(r - other.r, i - other.i, j - other.j, k - other.k);
  }

  Quaternion operator *(Quaternion other) {
    var newR = r * other.r - i * other.i - j * other.j - k * other.k;
    var newI = r * other.i + i * other.r + j * other.k - k * other.j;
    var newJ = r * other.j - i * other.k + j * other.r + k * other.i;
    var newK = r * other.k + i * other.j - j * other.i + k * other.r;
    return Quaternion._(newR, newI, newJ, newK);
  }

  double get norm => sqrt(pow(i, 2) + pow(j, 2) + pow(k, 2));

  Quaternion get conjugate => Quaternion._(r, -i, -j, -k);

  Quaternion get inverse {
    var conj = conjugate;
    var norm = this.norm;
    return conj * (1 / pow(norm, 2));
  }

  Quaternion get normalized => this / norm;

  Quaternion operator /(double scalar) {
    return Quaternion._(r / scalar, i / scalar, j / scalar, k / scalar);
  }

  @override
  String toString() {
    return 'Quaternion($r, $i, $j, $k)';
  }
}

