class Quaternion {
  final double w;
  final double x;
  final double y;
  final double z;

  Quaternion(this.w, this.x, this.y, this.z);

  static Quaternion identity = Quaternion(1, 0, 0, 0);

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      this.w + other.w,
      this.x + other.x,
      this.y + other.y,
      this.z + other.z,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      this.w - other.w,
      this.x - other.x,
      this.y - other.y,
      this.z - other.z,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      this.w * scalar,
      this.x * scalar,
      this.y * scalar,
      this.z * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    double w = this.w * other.w - this.x * other.x - this.y * other.y - this.z * other.z;
    double x = this.w * other.x + this.x * other.w + this.y * other.z - this.z * other.y;
    double y = this.w * other.y - this.x * other.z + this.y * other.w + this.z * other.x;
    double z = this.w * other.z + this.x * other.y - this.y * other.x + this.z * other.w;
    return Quaternion(w, x, y, z);
  }

  double norm() {
    return math.sqrt(w * w + x * x + y * y + z * z);
  }

  Quaternion normalize() {
    double n = this.norm();
    if (n == 0) {
      return Quaternion(1, 0, 0, 0);
    }
    return Quaternion(this.w / n, this.x / n, this.y / n, this.z / n);
  }

  Quaternion conjugate() {
    return Quaternion(this.w, -this.x, -this.y, -this.z);
  }

  Quaternion inverse() {
    Quaternion conjugate = this.conjugate();
    double norm = this.norm();
    if (norm == 0) {
      return Quaternion(1, 0, 0, 0);
    }
    return conjugate * (1 / (norm * norm));
  }

  @override
  String toString() {
    return 'Quaternion($w, $x, $y, $z)';
  }
}

