class Quaternion {
  double w;
  double x;
  double y;
  double z;

  Quaternion(this.w, this.x, this.y, this.z);

  factory Quaternion.fromAxisAngle(Vector3 axis, double angle) {
    double halfAngle = angle / 2;
    double sa = sin(halfAngle);
    double ca = cos(halfAngle);
    return Quaternion(ca, axis.x * sa, axis.y * sa, axis.z * sa);
  }

  Vector3 toAxisAngle() {
    double norm = norm();
    if (norm < 1e-6) {
      return Vector3(1, 0, 0);
    }
    double halfAngle = acos(w / norm);
    double sa = sin(halfAngle);
    return Vector3(x / norm, y / norm, z / norm) * (2 * halfAngle / sa);
  }

  double norm() => x * x + y * y + z * z;

  Quaternion normalized() {
    double n = norm();
    if (n < 1e-6) return Quaternion(1, 0, 0, 0);
    return Quaternion(w / sqrt(n), x / sqrt(n), y / sqrt(n), z / sqrt(n));
  }

  Quaternion conjugate() => Quaternion(w, -x, -y, -z);

  Quaternion inverse() => conjugate() * (1 / norm());

  Quaternion operator + (Quaternion other) =>
      Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);

  Quaternion operator - (Quaternion other) =>
      Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);

  Quaternion operator * (double scalar) =>
      Quaternion(w * scalar, x * scalar, y * scalar, z * scalar);

  Quaternion operator * (Quaternion other) {
    double nw = w * other.w - x * other.x - y * other.y - z * other.z;
    double nx = w * other.x + x * other.w + y * other.z - z * other.y;
    double ny = w * other.y - x * other.z + y * other.w + z * other.x;
    double nz = w * other.z + x * other.y - y * other.x + z * other.w;
    return Quaternion(nw, nx, ny, nz);
  }

  double get magnitude => sqrt(norm());

  @override
  String toString() => 'Quaternion($w, $x, $y, $z)';
}

