  Quaternion get normalized => this / norm;

  Quaternion operator +(Quaternion other) => Quaternion(
        w + other.w,
        x + other.x,
        y + other.y,
        z + other.z,
      );

  Quaternion operator -(Quaternion other) => Quaternion(
        w - other.w,
        x - other.x,
        y - other.y,
        z - other.z,
      );

  Quaternion operator *(double scalar) => Quaternion(
        w * scalar,
        x * scalar,
        y * scalar,
        z * scalar,
      );

  Quaternion operator *(Quaternion other) => Quaternion(
        w * other.w - x * other.x - y * other.y - z * other.z,
        w * other.x + x * other.w + y * other.z - z * other.y,
        w * other.y - x * other.z + y * other.w + z * other.x,
        w * other.z + x * other.y - y * other.x + z * other.w,
      );

  Quaternion get conjugate => Quaternion(w, -x, -y, -z);

  Quaternion get inverse => this / (norm * norm);

  @override
  String toString() => 'Quaternion($w, $x, $y, $z)';

  @override
  bool operator ==(Object other) =>
      other is Quaternion &&
      w == other.w &&
      x == other.x &&
      y == other.y &&
      z == other.z;

  @override
  int get hashCode =>
      w.hashCode ^ x.hashCode ^ y.hashCode ^ z.hashCode;
}

