class Quaternion {
  double w, x, y, z;

  Quaternion(this.w, this.x, this.y, this.z);

  double norm() => math.sqrt(w * w + x * x + y * y + z * z);

  Quaternion conjugate() => Quaternion(w, -x, -y, -z);

  Quaternion inverse() => conjugate() / norm().squared;

  Quaternion operator + (Quaternion other) =>
    Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);

  Quaternion operator - (Quaternion other) =>
    Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);

  Quaternion operator * (Quaternion other) =>
    Quaternion(
      w * other.w - x * other.x - y * other.y - z * other.z,
      w * other.x + x * other.w + y * other.z - z * other.y,
      w * other.y - x * other.z + y * other.w + z * other.x,
      w * other.z + x * other.y - y * other.x + z * other.w,
    );

  Quaternion operator * (double scalar) =>
    Quaternion(w * scalar, x * scalar, y * scalar, z * scalar);

  Quaternion operator / (double scalar) =>
    Quaternion(w / scalar, x / scalar, y / scalar, z / scalar);

  double get squared => w * w + x * x + y * y + z * z;

  @override
  String toString() => 'Quaternion($w, $x, $y, $z)';
}

