/// Computes the greatest common divisor of two integers using the Euclidean algorithm.
int gcd(int a, int b) {
  while (b != 0) {
    int t = b;
    b = a % b;
    a = t;
  }
  return a;
}

/// Computes the extended greatest common divisor of two integers.
/// Returns a tuple (g, x, y) such that a*x + b*y = g, where g = gcd(a, b).
List<int> extGcd(int a, int b) {
  if (a == 0) {
    return [b, 0, 1];
  }
  if (b == 0) {
    return [a, 1, 0];
  }
  List<int> r = extGcd(b, a % b);
  return [r[0], r[2], r[1] - (a ~/ b) * r[2]];
}

/// Computes the modular inverse of a modulo m using the extended Euclidean algorithm.
/// Returns the modular inverse if it exists (a and m are coprime), otherwise returns -1.
int modInverse(int a, int m) {
  List<int> r = extGcd(a, m);
  int g = r[0];
  if (g != 1) {
    return -1; 
  }
  int x = r[1];
  return (x % m + m) % m; 
}

