    int rank;
    switch (rankChar) {
      case 'A': rank = 1; break;
      case 'J': rank = 11; break;
      case 'Q': rank = 12; break;
      case 'K': rank = 13; break;
      default: {
        int? parsed;
        if ((parsed = int.tryParse(rankChar)) != null && parsed >= 2 && parsed <= 10) {
          rank = parsed;
        } else {
          return false;
        }
      }
    }
    if (rank < 2 || rank > 10 && rank != 11 && rank != 12 && rank != 13) return false;
    int cardValue = rank == 1 ? 11 : (rank == 11 ? 10 : rank);
    total += count * cardValue;
  }
  return total == expectedTotal;
}

