List<String> fn0(List<String> grid, String target, String corrected) {
  if (grid.isEmpty || grid[0].isEmpty) return [];
  int rows = grid.length;
  int cols = grid[0].length;
  if (target.isEmpty || corrected.isEmpty || target != grid[0][0]) return [];
  List<String> edits = [];
  void dfs(int r, int c, String path) {
    if (path.length > 3) return;
    if (r < 0 || c < 0 || r >= rows || c >= cols) return;
    String cell = grid[r][c];
    if (cell == target) {
      path = path.isEmpty ? cell : path + cell;
      if (path.length > 3) return;
      if (path == corrected) edits.add(path);
      dfs(r + 1, c, path);
      dfs(r - 1, c, path);
      dfs(r, c + 1, path);
      dfs(r, c - 1, path);
    } else {
      String newPath = path.isEmpty ? cell + cell : path + cell;
      if (newPath.length > 3) return;
      dfs(r + 1, c, newPath);
      dfs(r - 1, c, newPath);
      dfs(r, c + 1, newPath);
      dfs(r, c - 1, newPath);
    }
  }
  dfs(0, 0, '');
  edits.sort();
  return edits;
}

