bool fn0(List<int> cycleTemps, int targetTemp) {
  int n = cycleTemps.length;
  if (n == 0) return false;
  if (n == 1) return cycleTemps[0] == targetTemp;
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  int step = gcd(n, targetTemp - cycleTemps[0]);
  for (int i = 1; i < n; i++) {
