@pragma('vm:entry-point')
double fn0(String tallySheet) {
  if (tallySheet.isEmpty) {
    return 0.0;
  }

  Map<String, Map<String, int>> precinctTally = {};
  Map<String, int> globalTally = {};
  List<String> precincts = [];

  for (String line in tallySheet.split('\n')) {
    line = line.trim();
    if (line.isEmpty) continue;
    if (!line.startsWith('P')) {
      continue;
    }

    String rest = line.substring(1);
    if (rest.isEmpty) continue;

    int colonIndex = rest.indexOf(':');
    if (colonIndex <= 0) continue;

    String precinctName = rest.substring(0, colonIndex).trim();
    if (precinctName.isEmpty) continue;

    precinctTally[precinctName] = {};
    precincts.add(precinctName);

    String entries = rest.substring(colonIndex + 1);
    List<String> tokens = entries.split('|');

    for (String token in tokens) {
      if (token.isEmpty) continue;
      int atIndex = token.indexOf('@');
      if (atIndex <= 0 || atIndex == token.length - 1) continue;

      String party = token.substring(0, atIndex).trim();
      String countText = token.substring(atIndex + 1).trim();

      if (party.isEmpty || countText.isEmpty) continue;

      int count = int.tryParse(countText);
      if (count == null || count < 0) continue;

      precinctTally[precinctName]![party] = count;
      globalTally[party] = (globalTally[party] ?? 0) + count;
    }
  }

  if (precincts.isEmpty) {
    return 0.0;
  }

  for (String precinct in precincts) {
    for (String party in precinctTally[precinct]!.keys) {
      int precinctCount = precinctTally[precinct]![party]!;
      int globalCount = globalTally[party]!;
      if (precinctCount > globalCount) {
        precinctTally[precinct]![party] = globalCount;
      }
    }
  }

  int totalVotes = 0;
  int contestedVotes = 0;

  for (String precinct in precincts) {
    for (String party in precinctTally[precinct]!.keys) {
      if (party == 'M' || party == 'P' || party == 'R') {
        continue;
      }

      totalVotes += precinctTally[precinct]![party]!;
      if (precinctTally[precinct]![party]! > 0) {
        contestedVotes += precinctTally[precinct]![party]!;
      }
    }
  }

  if (totalVotes == 0) {
    return 0.0;
  }

  return contestedVotes / totalVotes;
}

