double fn0(List<String> log) {
  double total = 0.0;
  List<String> inventory = [];
  Map<String, int> pending = {};
  for (String entry in log) {
    List<String> parts = entry.split(':');
    String action = parts[0];
    if (action == 'P') {
      String item = parts[1];
      int count = int.parse(parts[2]);
      inventory.add(item);
      pending[item] = (pending[item] ?? 0) + count;
    } else if (action == 'B' || action == 'D') {
      String item = parts[1];
      int count = int.parse(parts[2]);
      if (pending.containsKey(item) && pending[item]! >= count) {
        pending[item] = pending[item]! - count;
        total += count * 0.5;
      }
    } else if (action == 'R') {
      String item = parts[1];
      int count = int.parse(parts[2]);
      for (int i = 0; i < inventory.length; i++) {
        if (inventory[i] == item) {
          inventory.removeAt(i);
          total += count * 0.25;
          break;
        }
      }
    } else if (action == 'M') {
      for (String item in inventory) {
        if (item == parts[1]) {
          total += 0.5;
          break;
        }
      }
    } else if (action == 'S') {
      String item = parts[1];
      if (inventory.contains(item)) {
        total += 0.25;
      }
    }
  }
  return total;
}

