  int pos = 0;
  int score = 0;
  double total = 0.0;
  for (String token in tokens) {
    String t = token.trim();
    if (t == '') continue;
    if (t.startsWith('B')) {
      history.add([pos, score]);
      pos = 0;
    } else if (t == 'C') {
      if (history.isNotEmpty) {
        List<int> prev = history.removeLast();
        pos = prev[0];
        score = prev[1];
      }
    } else if (t == 'D') {
      if (history.isNotEmpty) {
        List<int> prev = history.last;
        total += (pos - prev[0]).toDouble();
        score = prev[1] + (pos - prev[0]);
      }
    } else if (t == 'M') {
      if (history.isNotEmpty) {
        List<int> prev = history.last;
        score = prev[1] + 10;
      }
    } else if (t == 'P') {
      total += (pos).toDouble();
    } else if (t == 'R') {
      if (history.isNotEmpty) {
        List<int> prev = history.last;
        total += (pos - prev[0]).toDouble();
        score = prev[1] + (pos - prev[0]);
      }
      history.add([pos, score]);
    } else if (t == 'S') {
      if (history.isNotEmpty) {
        List<int> prev = history.removeLast();
        if (history.isNotEmpty) {
          List<int> next = history.last;
          total += (next[0] - prev[0]).toDouble();
          score = next[1] + (next[0] - prev[0]);
        }
      }
    }
  }
  return total;
}

