      count = fullBlocks * 5;
      if (rem >= 3) count += 3;
    } else if (prefix == 'M') {
      int bodyLen = body.length;
      int fullBlocks = bodyLen ~/ 2;
      count = fullBlocks * 2;
    } else if (prefix == 'R') {
      hasR = true;
