      }
    } else if (action == 'end') {
      if (stack.isNotEmpty) {
        String last = stack.removeLast();
        if (last != parts[1].trim()) {
          results.add('$last ${parts[1].trim()}');
        }
      }
    }
  }
  while (stack.isNotEmpty) {
    results.add('${stack.removeLast()} <unmatched>');
  }
  return results;
}

