bool fn0(List<String> symbols, int minLength) {
  int n = symbols.length;
  if (n == 0) return true;
  List<bool> dp = List<bool>.filled(n + 1, false);
  dp[0] = true;
  for (int i = 1; i <= n; i++) {
    int maxLen = 0;
    for (int j = i - 1; j >= 0; j--) {
      int len = i - j;
      if (len > maxLen) maxLen = len;
      if (dp[j]) {
        String sub = symbols.sublist(j, i).join('');
        if (sub.length >= minLength) {
          int left = 0;
          int right = sub.length - 1;
          bool isBalanced = true;
          while (left < right) {
            if (sub[left] != sub[right]) {
              isBalanced = false;
              break;
            }
            left++;
            right--;
          }
          if (isBalanced) {
            dp[i] = true;
            break;
          }
        }
      }
    }
  }
  return dp[n];
}

