        openNames.remove(name);
      }
      result += "CLOSE:$name:$count";
    } else if (type == 'D') {
      if (currentStatus != "OPEN") {
        result += "D:$rest:NOTOPEN";
        continue;
      }
      int amount = int.tryParse(rest) ?? 0;
      if (amount <= 0) {
        result += "D:$rest:NEGATIVE";
        continue;
      }
      history.add(rest);
      net += amount;
      result += "D:$rest:$count";
    }
  }

  while (openNames.isNotEmpty) {
    String name = openNames.removeLast();
    int count = balances[name] ?? 0;
    result += ",OPEN:$name:$count";
  }

  if (result.isEmpty) {
    result = "FINAL:net=$net";
  } else {
    result = "FINAL:$result,net=$net";
  }

