  List<String> results = [];

  for (int i = 0; i < schedule.length; i++) {
    String ch = schedule[i];
    if (ch == 'C') {
      events.add('CLOSE:$i');
      balance++;
    } else if (ch == 'D') {
      events.add('OPEN:$i');
      balance--;
    }
  }

  int windowStart = -1;
  int windowEnd = -1;
  int maxNet = int.MinValue;
  int maxDay = -1;

  for (int i = 0; i < events.length; i++) {
    String event = events[i];
    int pos = event.indexOf(':');
