    if (day >= startDay && day <= endDay) {
      if (windowStart == -1) {
        windowStart = day;
      }
      windowEnd = day;
      int net = balance - (day - startDay);
      if (net > maxNet) {
        maxNet = net;
        maxDay = day;
      }
    }
  }

  events = events.map((event) {
    String result = event;
    if (event == 'CLOSE:$windowStart' && windowStart != -1) {
      result += ',result=open';
    } else if (event == 'OPEN:$windowEnd' && windowEnd != -1) {
      result += ',result=close';
    }
    return result;
  }).toList();

  events.sort((a, b) {
    String resultA = a.split(',').last;
    String resultB = b.split(',').last;

    bool isOpenA = resultA == 'open';
    bool isOpenB = resultB == 'open';

    if (isOpenA != isOpenB) return isOpenA ? -1 : 1;

    int closeDayA = int.parse(a.split(':').last);
    int closeDayB = int.parse(b.split(':').last);

    return closeDayA.compareTo(closeDayB);
  });

  return events;
}

