List<int> fn0(String dna, int k) {
  if (k <= 0) return [];
  List<String> bases = ['A', 'C', 'G', 'T'];
  Map<String, int> baseIndex = {for (int i = 0; i < bases.length; i++) bases[i]: i};
  if (!dna.toUpperCase().containsOnlyOf(bases)) return [];

  int n = dna.length;
  if (n < k) return [];

  Map<int, int> dp;
  Map<int, int> maxFreq;
  List<int> result = [];

  void search(int pos, int mask, int count, int prevBaseIndex, bool canSkip) {
    if (count == k) {
      int popcount = 0;
      int tmp = mask;
      while (tmp > 0) {
        popcount += tmp & 1;
        tmp >>= 1;
      }
      result.add(popcount);
      return;
    }

    int end = pos + (canSkip ? 1 : 0);
    for (int i = pos; i < end && i < n; i++) {
      int b = baseIndex[dna[i].toUpperCase()]!;
      int nextCanSkip = canSkip && (i + 1 < n && baseIndex[dna[i + 1].toUpperCase()]! != b);

      if (mask != 0) {
        int bit = (mask >> b) & 1;
        if (bit == 1) {
          mask = mask ^ (1 << b);
        }
      }

      if (mask != 0) {
        int tmp = mask;
        int tmpCount = 0;
        while (tmp > 0) {
          tmpCount += tmp & 1;
          tmp >>= 1;
        }
        if (tmpCount >= 4) {
          return;
        }
      }

      int nextMask = mask;
      if (nextMask != 0) {
        nextMask = nextMask ^ (1 << b);
      } else {
        nextMask = 1 << b;
      }

      int nextPrevBaseIndex = b;
      if (count == 0) {
        nextPrevBaseIndex = -1;
      }

      bool sameConsecutive = count > 0 &&
          nextPrevBaseIndex == b &&
          (canSkip && i + 1 < n && baseIndex[dna[i + 1].toUpperCase()] == b);
      if (sameConsecutive) {
        return;
      }

      int nextCount = count + 1;
      if (nextCount >= 4) {
        return;
      }

      search(i + 1, nextMask, nextCount, nextPrevBaseIndex, nextCanSkip);
    }
  }

  dp = {};
  maxFreq = {};
  search(0, 0, 0, -1, true);
  result.sort();
  return result;
}

