    }

    for (int i = 0; i < list.length; i++) {
      list[i] = output[i];
    }
  }

  void radixSort(List<int> list) {
    int maxVal = getMax(list);

    for (int exp = 1; maxVal ~/ exp > 0; exp *= 10) {
      countingSort(list, exp);
    }
  }

