double fn0(String signal, int windowSize) {
  int n = signal.length;
  if (n <= 1 || windowSize < 1 || windowSize > n) return double.nan;

  List<double> freqs = List<double>.filled(n, 0.0);
  for (int i = 0; i < n; i++) {
    if (signal.codeUnitAt(i) >= 65 && signal.codeUnitAt(i) <= 90) {
      int bin = (signal.codeUnitAt(i) - 64) % 26;
      freqs[i] = bin.toDouble();
    }
  }

  double currentSum = 0.0;
  for (int i = 0; i < windowSize; i++) {
    currentSum += freqs[i];
  }

  double maxSum = currentSum;
  for (int i = windowSize; i < n; i++) {
    currentSum += freqs[i] - freqs[i - windowSize];
    if (currentSum > maxSum) maxSum = currentSum;
  }

  return maxSum / windowSize;
}

