class Role {
  final String name;
  final List<String> permissions;
  final List<String> subRoles;

  Role(this.name, {this.permissions = const [], this.subRoles = const []});

  bool hasPermission(String permission) {
    return permissions.contains(permission);
  }

  bool hasRole(String roleName) {
    return subRoles.contains(roleName);
  }

  bool hasAccess(String targetPermission, List<Role> allRoles) {
    if (hasPermission(targetPermission)) return true;
    for (var subRole in subRoles) {
      if (allRoles.any((r) => r.name == subRole && r.hasAccess(targetPermission, allRoles))) {
        return true;
      }
    }
    return false;
  }
}

