    if (roles.contains(role)) {
      auditLog.add('User $name added duplicate role $role (ID: $id, Timestamp: $timestamp)');
    } else {
      roles.add(role);
      currentRole = role;
      auditLog.add('User $name added role $role (ID: $id, Timestamp: $timestamp)');
    }
  }

  void removeRole(String role) {
    if (roles.contains(role)) {
      roles.remove(role);
      if (currentRole == role) {
        currentRole = roles.isNotEmpty ? roles[0] : '';
      }
      auditLog.add('User $name removed role $role (ID: $id, Timestamp: $timestamp)');
    } else {
      auditLog.add('User $name attempted to remove non-existent role $role (ID: $id, Timestamp: $timestamp)');
    }
  }
}

