    this.role = 'user',
    this.status = 'active',
    this.isVerified = false,
    this.isAdmin = false,
    this.isArchived = false,
  });

  void promoteToAdmin() {
    if (!isAdmin && !isArchived) {
      isAdmin = true;
      role = 'admin';
      status = 'active';
      print('✅ User $name promoted to admin');
    } else {
      print('❌ Cannot promote $name: already admin or archived');
    }
  }

  void demoteToUser() {
    if (isAdmin && !isArchived) {
      isAdmin = false;
      role = 'user';
      print('✅ Admin $name demoted to user');
    } else {
      print('❌ Cannot demote $name: not admin or archived');
    }
  }

  void archive() {
    if (!isArchived && !isAdmin) {
      isArchived = true;
      status = 'archived';
      print('✅ User $name archived');
    } else {
      print('❌ Cannot archive $name: already archived or admin');
    }
  }

  void unarchive() {
    if (isArchived) {
      isArchived = false;
      status = 'active';
      print('✅ User $name unarchived');
    } else {
      print('❌ $name is not archived');
    }
  }

  void verify() {
    if (!isVerified && !isArchived) {
      isVerified = true;
      status = 'verified';
      print('✅ User $name verified');
    } else {
      print('❌ Cannot verify $name: already verified or archived');
    }
  }

  @override
  String toString() {
    return 'User{id: $id, name: $name, role: $role, status: $status, '
        'verified: $isVerified, admin: $isAdmin, archived: $isArchived}';
  }
}

