      itemFrequency[item] = (itemFrequency[item] ?? 0) + 1;
    }
  }

  int minSupport = 2;

  Map<Set<String>, int> frequentItemsets = {};
  for (var entry in itemFrequency.entries) {
    if (entry.value >= minSupport) {
      var set = <String>{entry.key};
      frequentItemsets[set] = entry.value;
    }
  }

  List<Set<String>> frequentItemsetsList = frequentItemsets.keys.toList()
    ..sort((a, b) => a.length.compareTo(b.length));

  for (int length = 2; frequentItemsetsList.isNotEmpty; length++) {
    Map<Set<String>, int> newFrequentItemsets = {};

    for (var itemset in frequentItemsetsList) {
      if (itemset.length != length - 1) continue;

      for (var other in frequentItemsetsList) {
        if (other.length != length - 1) continue;
        if (itemset == other) continue;

        Set<String> union = Set<String>.from(itemset);
        union.addAll(other);

        int support = frequentItemsets[itemset]! + frequentItemsets[other]!;
        if (support < minSupport) continue;

        bool meetsMIS = true;
        for (var candidate in union) {
          Set<String> subset = Set<String>.from(union);
          subset.remove(candidate);
          if (frequentItemsets[subset]! < minSupport) {
            meetsMIS = false;
            break;
          }
        }

        if (meetsMIS) {
          newFrequentItemsets[union] = support;
        }
      }
    }

    if (newFrequentItemsets.isEmpty) break;

    frequentItemsets = newFrequentItemsets;
    frequentItemsetsList = frequentItemsets.keys.toList()
      ..sort((a, b) => a.length.compareTo(b.length));
  }

  print('Frequent Itemsets:');
  for (var itemset in frequentItemsets.keys) {
    print('${itemset.toList()} (support: ${frequentItemsets[itemset]})');
  }

  Map<Set<String>, Set<String>> associationRules = {};

  for (var itemset in frequentItemsets.keys) {
    for (var subset in itemset.subsets()) {
      Set<String> antecedent = Set<String>.from(subset);
      Set<String> consequent = Set<String>.from(itemset);
      consequent.removeAll(antecedent);

      if (antecedent.isEmpty) continue;

      double confidence = frequentItemsets[itemset]! / frequentItemsets[antecedent]!;
      if (confidence >= 0.7) {
        associationRules.putIfAbsent(antecedent, () => <String>{});
        associationRules[antecedent]!.add(consequent.first);
      }
    }
  }

  print('\nAssociation Rules:');
  for (var entry in associationRules.entries) {
    String antecedentStr = entry.key.toList()..sort().join(', ');
    for (var consequent in entry.value) {
      print('${antecedentStr} => $consequent (confidence: ${entry.key.length}/${itemset.length} → ${double.parse(associationRules[entry.key]!.length.toString()) / double.parse(itemset.length.toString())})');
    }
  }
}

