List<int> fn0(List<int> quantities, int base, int numRounds) {
  List<List<int>> dp = List.generate(numRounds + 1, (_) => List<int>.filled(quantities.length, 0));
  for (int i = 0; i < quantities.length; i++) {
    dp[0][i] = quantities[i];
  }
  for (int r = 1; r <= numRounds; r++) {
    for (int i = 0; i < quantities.length; i++) {
      int best = 1 << 30;
      for (int j = 0; j < quantities.length; j++) {
        if (i == j) continue;
        int cost = dp[r - 1][j].abs() + (dp[r - 1][i] - dp[r - 1][j]).abs();
        if (cost < best) best = cost;
      }
      dp[r][i] = (dp[r - 1][i] + base) ~/ 2;
      int target = dp[r][i];
      if (best != 1 << 30) {
        int diff = (target - base).abs();
        int newTarget = target;
        int minDist = diff;
        for (int shift = 1; shift <= 4; shift++) {
          int alt = target - shift * base;
          int dist = (alt - base).abs() + (target - alt).abs();
          if (dist < minDist) {
            minDist = dist;
            newTarget = alt;
          }
          alt = target + shift * base;
          dist = (alt - base).abs() + (target - alt).abs();
          if (dist < minDist) {
            minDist = dist;
            newTarget = alt;
          }
        }
        dp[r][i] = newTarget;
      }
    }
  }
  return dp[numRounds];
}

