bool fn0(List<int> samplePings, int maxLatency) {
  if (samplePings.length % 2 != 0) {
    return false;
  }
  if (samplePings.isEmpty) {
    return true;
  }

  int n = samplePings.length;
  int limit = n ~/ 2;
  List<int> sorted = List<int>.from(samplePings);
  sorted.sort();

  int minGap = sorted[n - 1] - sorted[0];

  for (int split = 1; split <= limit; split++) {
    List<int> left = sorted.sublist(0, split);
    List<int> right = sorted.sublist(split);

    int leftMin = left[0];
    int leftMax = left[left.length - 1];
    int rightMin = right[0];
    int rightMax = right[right.length - 1];

    if (leftMin > rightMax || rightMin > leftMax) {
      continue;
    }

    int gap = leftMax - rightMin;
    if (gap < 0) {
      gap = -gap;
    }
    if (gap < minGap) {
      minGap = gap;
    }
  }

  return minGap <= maxLatency;
}

