  int sum = 0;
  for (int i = 0; i < digits.length; i++) {
    if (digits[i] < 0 || digits[i] > 9) return {};
    sum += digits[i];
  }
  if (sum != expectedSum) return {};
  int patternLength = 0;
  int temp = digitSumPattern;
  while (temp > 0) {
    patternLength++;
    temp >>= 1;
  }
  if (patternLength == 0) return {};
  int n = digits.length;
  if (n % patternLength != 0) return {};
  int segmentSize = n ~/ patternLength;
  List<int> segmentSums = List.filled(segmentSize, 0);
  int patternIdx = 0;
  for (int i = 0; i < n; i++) {
    int powSum = 0;
    for (int p = 0; p < patternLength; p++) {
      int bit = (digitSumPattern >> p) & 1;
      powSum += bit * (digits[i + p] ~/ 10);
    }
    segmentSums[patternIdx] += powSum;
    patternIdx++;
    if (patternIdx == patternLength) {
      patternIdx = 0;
    }
  }
  int totalPatternSum = 0;
  for (int s in segmentSums) {
    totalPatternSum += s;
  }
  if (totalPatternSum == 0) return {};
  int gcd = segmentSums[0];
  for (int i = 1; i < segmentSums.length; i++) {
    while (segmentSums[i] != 0) {
      int t = segmentSums[i];
      segmentSums[i] = gcd % segmentSums[i];
      gcd = t;
    }
  }
  if (gcd != 0) {
    for (int i = 0; i < segmentSums.length; i++) {
      segmentSums[i] ~/= gcd;
    }
  }
