      for (int d = 2; d * d <= p; d++) {
        if (p % d == 0) {
          smallestPrime = d;
          break;
        }
      }
      if (smallestPrime == -1) smallestPrime = p;
      result.add(smallestPrime);
    }
  }
  return result;
}

