  if (reservedIndex != -1) {
    String suffix = result.substring(reservedIndex + 8);
    int weight = int.parse(suffix);
    if (weight % 2 == 0) {
      return result.substring(0, reservedIndex + 8) + (weight + 1).toString();
    }
    return result.substring(0, reservedIndex) + 'S' + result.substring(reservedIndex + 8);
  }
  int oversizedIndex = result.indexOf('OVERSIZE');
