    int colon = line.indexOf(':');
    String levelStr = line.substring(0, colon);
    int level = int.parse(levelStr);
    levels.add(levelStr);
    parents.add(level == 0 ? '' : line);
  }
  List<int> indexByLevel = List<int>.filled(logLines.length, -1);
  int count = 0;
  for (String level in levels) {
    int l = int.parse(level);
