  }
  List<String> result = List<String>.filled(logLines.length, '');
  void dfs(int i) {
    int level = int.parse(levels[i]);
    String parentLine = parents[i];
    String label = parentLine.isEmpty ? '#' : parentLine;
    result[i] = label;
    for (int j = indexByLevel[level + 1]; j >= 0; j--) {
      dfs(j);
    }
  }
  dfs(0);
  return result;
}

