        (right - left + 1) >= minSize &&
        (right - left + 1) <= maxSize) {
      int len = right - left + 1;
      if (len > maxLen) {
        maxLen = len;
        bestStart = left;
        bestEnd = right;
      } else if (len == maxLen && left < bestStart) {
        bestStart = left;
        bestEnd = right;
      }
    }
  }
  if (bestStart == -1) return [];
