    if (i == 0 || deficits[i] != deficits[i - 1]) distinct++;
  }
  var longest = 0;
  for (var i = 1; i < deficits.length; i++) {
    if (deficits[i] > longest) longest = deficits[i];
  }
  return {
    'totalDeficitDays': totalDeficit,
    'distinctIntervals': distinct,
    'longestInterval': longest
  };
}

