    if (ch == '(') return 1;
    if (ch == '|') return 2;
    if (ch == '&') return 3;
    return 0;
  }
  List<String> result = [];
  for (String phase in phases) {
    List<String> stack = [];
    for (int i = 0; i < phase.length; i++) {
      String ch = phase[i];
      if (ch == '(') {
        stack.add(ch);
      } else if (ch == ')') {
        if (stack.isEmpty) stack.add(ch);
        else {
          while (stack.isNotEmpty && stack.last != '(') {
            stack.removeLast();
          }
          if (stack.isNotEmpty && stack.last == '(') stack.removeLast();
        }
      } else if (ch == '&' || ch == '|') {
        while (stack.isNotEmpty && precedence(stack.last) >= precedence(ch)) {
          stack.removeLast();
        }
        stack.add(ch);
      } else {
        stack.add(ch);
      }
    }
    while (stack.isNotEmpty) {
      result.add(stack.removeLast());
    }
  }
  return result;
}

