List<String> fn0(List<List<int>> grid, int threshold) {
  if (grid.isEmpty || grid[0].isEmpty) {
    return [];
  }

  int rows = grid.length;
  int cols = grid[0].length;
  List<List<double>> centroids = [];

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int val = grid[r][c];
      if (val >= threshold) {
        bool isCentroid = true;
        for (List<double> centroid in centroids) {
          double dx = (r - centroid[0]).abs();
          double dy = (c - centroid[1]).abs();
          if (dx + dy <= 1) {
            isCentroid = false;
            break;
          }
        }
        if (isCentroid) {
          centroids.add([r.toDouble(), c.toDouble()]);
        }
      }
    }
  }

  List<String> result = [];
  for (int i = 0; i < centroids.length; i++) {
    List<double> c = centroids[i];
    int dist = 999999;
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (grid[r][c] >= threshold) {
          int d = (r - c).abs();
          if (d < dist) {
            dist = d;
          }
        }
      }
    }
    result.add('Day ${i + 1}: ${c[0].toInt()}, ${c[1].toInt()} - $dist cm');
  }

  return result;
}

