    [1.0, 2.0],
    [1.5, 1.8],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.6],
    [9.0, 11.0],
    [8.0, 2.0],
    [10.0, 2.0],
    [9.0, 3.0],
  ];

  int k = 2; 

  int maxIterations = 100;
  double tolerance = 0.001; 

  if (k <= 0 || k > points.length) {
    print('Number of clusters (k) must be between 1 and the number of data points.');
    return;
  }

  List<double> centroids = List<double>.generate(k, (i) => Random().nextDouble() * 10 - 5);

  bool centroidsChanged = true;
  int iteration = 0;

  while (centroidsChanged && iteration < maxIterations) {
    iteration++;

    List<List<int>> assignments = List.generate(points.length, (_) => List.filled(k, 0));

    for (int i = 0; i < points.length; i++) {
      double minDist = double.infinity;
      for (int c = 0; c < k; c++) {
        double dist = (points[i][0] - centroids[c]) * (points[i][0] - centroids[c]) +
                      (points[i][1] - centroids[c]) * (points[i][1] - centroids[c]);
        if (dist < minDist) {
          minDist = dist;
          assignments[i][0] = c;
        }
      }
    }

    List<double> newCentroids = List.filled(k, 0.0);
    List<int> counts = List.filled(k, 0);

    for (int i = 0; i < points.length; i++) {
      int clusterIdx = assignments[i][0];
      newCentroids[clusterIdx] += points[i][0];
      newCentroids[clusterIdx] += points[i][1];
      counts[clusterIdx]++;
    }

    bool anyClusterEmpty = false;
    for (int c = 0; c < k && !anyClusterEmpty; c++) {
      if (counts[c] == 0) anyClusterEmpty = true;
    }
    if (anyClusterEmpty) break;

    for (int c = 0; c < k; c++) {
      newCentroids[c] = newCentroids[c] / counts[c];
    }

    centroidsChanged = false;
    for (int c = 0; c < k; c++) {
      if (centroids[c] != newCentroids[c]) {
        centroidsChanged = true;
      }
      centroids[c] = newCentroids[c];
    }
  }

  print('Cluster centroids:');
  for (int i = 0; i < k; i++) {
    print('Cluster $i: ${centroids[i]}');
  }

  print('Points assigned to clusters:');
  for (int i = 0; i < points.length; i++) {
