    if (!zones.contains(zone)) {
      zones.add(zone);
    }

    for (String t in times) {
      int colonIdx = t.indexOf(':');
      int hour = int.parse(t.substring(0, colonIdx));
      int minute = int.parse(t.substring(colonIdx + 1, colonIdx + 2));
      String period = hour < 6 ? 'night' :
                      hour < 12 ? 'morning' :
                      hour < 18 ? 'day' : 'evening';

      if (!hourly.containsKey(zone)) {
        hourly[zone] = {};
      }
      if (!hourly[zone]!.containsKey(period)) {
        hourly[zone]![period] = [];
      }

      double temp = double.parse(parts[2]);
      if (minute == 0) {
        hourly[zone]![period]!.add(temp);
      } else {
        double startTemp = double.parse(parts[2]);
        double endTemp = double.parse(parts[3]);
        double rate = (endTemp - startTemp) / 60.0;
        double dt = minute.toDouble();
        hourly[zone]![period]!.add(startTemp + rate * dt);
      }
    }
  }

  zones.sort();

  List<String> result = [];
  for (String zone in zones) {
    Map<String, List<double>> zoneData = hourly[zone]!;
    List<String> periodOrder = sortedHours;

    for (String period in periodOrder) {
      if (zoneData.containsKey(period)) {
        double avg = zoneData[period]!.reduce((a, b) => a + b) / zoneData[period]!.length;
        result.add('${zone}${period.capitalize()} avg: ${avg.toStringAsFixed(1)}°F');
      }
    }
  }

