bool fn0(List<List<int>> chargeCycles, int maxCycles) {
  int rows = chargeCycles.length;
  if (rows == 0) return true;
  int cols = chargeCycles[0].length;
  if (cols == 0) return true;
  List<List<int>> dp = List.generate(
    rows,
    (_) => List.filled(cols, 0),
  );
  for (int r = 0; r < rows; r++) {
    dp[r][0] = chargeCycles[r][0];
  }
  for (int c = 1; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      int minAbove = dp[r][c - 1];
      for (int nr = r - 1; nr <= r + 1; nr++) {
        if (nr >= 0 && nr < rows) {
          if (dp[nr][c - 1] < minAbove) minAbove = dp[nr][c - 1];
        }
      }
      dp[r][c] = chargeCycles[r][c] + minAbove;
    }
  }
  int minFinal = dp[0][cols - 1];
  for (int r = 1; r < rows; r++) {
    if (dp[r][cols - 1] < minFinal) minFinal = dp[r][cols - 1];
  }
  return minFinal <= maxCycles;
}

