int fn0(List<int> packetSizes, int mtu) {
  if (packetSizes.isEmpty) return 0;
  List<int> dp = List.filled(packetSizes.length, 0);
  int maxSum = -1;
  for (int i = 0; i < packetSizes.length; i++) {
    if (packetSizes[i] > mtu) continue;
    int best = i == 0 ? 0 : dp[i - 1];
    for (int j = 0; j <= i; j++) {
      if (packetSizes[j] > mtu) break;
      int sum = 0;
      for (int k = j; k <= i; k++) {
        if (sum + packetSizes[k] > mtu) break;
        sum += packetSizes[k];
      }
      if (sum > best) best = sum;
    }
    dp[i] = best;
    if (best > maxSum) maxSum = best;
  }
  return maxSum;
}

