List<String> fn0(String dna, int maxRun) {
  if (dna.isEmpty) return [];
  List<String> result = [];
  int n = dna.length;
  int i = 0;
  while (i < n) {
    int count = 0;
    while (i + count < n && dna[i + count] == dna[i]) {
      count++;
    }
    int startChunk = i;
    int endChunk = i + count - 1;
    int chunkIndex = result.length;
    while (result.isNotEmpty && endChunk >= result.last.length) {
      String last = result.removeLast();
      if (last.length > startChunk) {
        result.add(last.substring(0, startChunk));
      }
      startChunk = last.length;
    }
    int run = count;
    while (run > maxRun) {
      int splitIndex = startChunk + maxRun;
      result.add(dna.substring(startChunk, splitIndex));
      startChunk = splitIndex;
      run -= maxRun;
    }
    if (result.isEmpty || startChunk > result.last.length) {
      result.add(dna.substring(startChunk));
    }
    result[chunkIndex] = dna.substring(startChunk, endChunk + 1);
    i += count;
  }
  return result;
}

