Set<int> fn0(List<int> requests, int maxFloor, int maxTravel, int minSize, int maxSize, int maxVariance, int serviceInterval) {
  if (requests.isEmpty || minSize > maxSize || minSize <= 0 || maxTravel <= 0 || maxFloor <= 0) return {};

  var req = List<int>.from(requests);
  req.sort();
  List<int> counts = List<int>.filled(maxFloor + 1, 0);
  for (int f in req) {
    if (f >= 0 && f <= maxFloor) {
      counts[f]++;
    }
  }
  int numGroups = 0;
  for (int c in counts) {
    if (c > 0) numGroups++;
  }

  if (numGroups <= 1) return {0};

  List<int> groupStarts = [];
  int currentGroupCount = 0;
  for (int f = 0; f <= maxFloor; f++) {
    if (counts[f] > 0) {
      currentGroupCount++;
    } else {
      if (currentGroupCount > 0) {
        groupStarts.add(f - currentGroupCount + 1);
        currentGroupCount = 0;
      }
    }
  }
  if (currentGroupCount > 0) {
    groupStarts.add(maxFloor - currentGroupCount + 1);
  }

  Set<int> result = {0};
  for (int g = 0; g < groupStarts.length; g++) {
    int start = groupStarts[g];
    int end = start + (counts[start] - 1);
    int groupCenter = start + (counts[start] ~/ 2);
    int groupSpan = end - start + 1;
    if (counts[start] > maxSize || counts[start] < minSize) continue;
    if (groupSpan > maxTravel) continue;

    for (int t = 0; t <= serviceInterval; t++) {
      int prevFloor = (t - 1).clamp(0, maxFloor);
      int travelDist = (t > 0 ? prevFloor : 0) - groupCenter;
      if (travelDist < 0) travelDist = -travelDist;
      if (travelDist <= maxTravel) {
        result.add(t);
      }
    }
  }

  return result;
}

