  int number = 120;

  if (number < 0) {
    print('$number is negative.');
  } else if (number > 0 && number <= 100) {
    print('$number is positive and up to 100.');
  } else if (number > 100) {
    print('$number is large positive.');
  } else {
    print('$number is zero.');
  }
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> numbers = [-8, 0, 42, 105, -200];

  for (int n in numbers) {
    switch (n) {
      case < 0:
        print('$n is negative.');
        break;
      case 0:
        print('$n is zero.');
        break;
      case > 0 && <= 100:
        print('$n is positive and up to 100.');
        break;
      case > 100:
        print('$n is large positive.');
        break;
    }
  }
}

